from robot.api import logger
from robot.utils.robottime import timestr_to_secs


from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsString


class DeprecatedInterface(BaseInterface):

    def reset_unit(self, dist_name, timeout=60, alias="default"):
        """Preform unit reset procedure.

        :param string dist_name: unit to reset dist name (RMOD/GNSS/RET/MHA).
                From SBTS17A onwards use runtime view dist name like:
                /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1/GNSSE_R-1 (tested on AirScale SBTS18A)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :note: Deprecated keyword. `Please use ute_admin.unit_reset_cp instead`.
        """

        logger.warn("Keyword ute_admin.reset_unit is deprecated. Please use ute_admin.unit_reset_cp instead.")

        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("unitReset", {"distName": dist_name}, timeout)

    def get_lnbts_operational_state(self, timeout=10, alias="default"):
        """Get LNBTS operational state.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: LNBTS operational state

        :note: Deprecated keyword. `Please use ute_admin.get_mrbts_state` instead.
        """
        logger.warn("Keyword ute_admin.get_lnbts_operational_state is deprecated. Please use ute_admin.get_mrbts_state instead.")

        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("lnbtsState", {}, timeout)

    def install_cmp_certificate(self, timeout=60, alias="default"):
        """Install CMP certificate.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """

        logger.warn(
            "Keyword ute_admin.install_cmp_certificate is deprecated. Please use ute_admin.cmp_initialize_certificate instead.")

        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure_then_old_procedure("installCmpCertificate", {}, timeout)

    @wrap_result
    def get_cell_mapping(self, timeout=10, alias="default"):
        """Get LNCEL to LCELL mapping

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of lncel to lcell mappings

        :note: Deprecated keyword. `Please use ute_admin.get_cell_mapping_by_module_id` or `ute_admin_infomodel.query_infomodel` instead.
        """
        logger.warn("Keyword ute_admin.get_cell_mapping is deprecated. "
                    "Please use ute_admin.get_cell_mapping_by_module_id or ute_admin_infomodel.query_infomodel instead.")

        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("getCellMapping", {}, timeout)

    @wrap_result
    def get_parameters(self, dist_name, pattern="", timeout=10, alias="default"):
        """Get object parameters.
        :param string dist_name: Object dist name.
        :param string pattern: Parameters name pattern (regex).
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: Object's parametrs dict filtered by pattern

        :note: Deprecated keyword. `Please use ute_admin.get_parameters_for` or `ute_admin_infomodel.get_infomodel_object` instead.
        """
        logger.warn("Keyword ute_admin.get_parameters is deprecated. "
                    "Please use ute_admin.get_parameters_for or ute_admin_infomodel.get_infomodel_object instead.")

        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        IsString().check(pattern)
        return self.store.get(alias).execute_infomodel_request("getParameters", {"distName": dist_name, "pattern": pattern}, timeout)

    @wrap_result
    def get_objects_by_class_name(self, class_name, timeout=10, alias="default"):
        """Get objects by class name.
        :param string class_name: InfoModel class name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of objects matching class name.

        :note: Deprecated keyword. Please use `ute_admin.get_parameters_for_all` or `ute_admin_infomodel.query_infomodel` instead.
        """
        logger.warn("Keyword ute_admin.get_objects_by_class_name is deprecated. "
                    "Please use ute_admin.get_parameters_for_all or ute_admin_infomodel.query_infomodel instead.")

        timeout = timestr_to_secs(timeout)
        IsString().check(class_name)
        return self.store.get(alias).execute_infomodel_request("getItemsByClassName", {"className": class_name}, timeout)

    def wait_for_parameters_value(self, dist_name_regex, timeout=10, alias="default", **parameters):
        """Wait for parameters value.
        :param string dist_name_regex: Object dist name regex.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :note: Deprecated keyword. Please use `ute_admin.assert_*` or `ute_admin_infomodel.query_infomodel` instead.
        """
        logger.warn("Keyword ute_admin.wait_for_parameters_value is deprecated. "
                    "Please use ute_admin.assert_* or ute_admin_infomodel.query_infomodel instead.")

        IsString().check(dist_name_regex)

        timeout = timestr_to_secs(timeout)
        paramList = [{"parameterPath": path, "value": value} for path, value in parameters.items()]
        return self.store.get(alias).execute_infomodel_request(
            "waitForParameterValue", {"distNameRegEx": dist_name_regex, "timeout": timeout * 1000, "parametersList": paramList}, timeout + 10)

    def wait_for_alarm_presence(self, parent_dist_name, timeout=10, alias="default", **alarm_properties):
        """Wait for alarm presence. Checks if alaram with given parameters exists.
        :param string parent_dist_name: Parent object dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: object
        :return: matching alarm object

        :note: Deprecated keyword. Please use `ute_admin.assert_alarm_active` or `ute_admin_infomodel.query_infomodel` instead.
        """
        logger.warn("Keyword ute_admin.wait_for_alarm_presence is deprecated. "
                    "Please use ute_admin.assert_alarm_active or ute_admin_infomodel.query_infomodel instead.")

        return self._wait_for_alarm("presence", parent_dist_name, alarm_properties, timeout, alias)

    def wait_for_alarm_deletion(self, parent_dist_name, timeout=10, alias="default", **alarm_properties):
        """Wait for alarm deletion. Checks if alaram with given parameters not exist.
        :param string parent_dist_name: Parent object dist name.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :note: Deprecated keyword. Please use `ute_admin.assert_alarm_inactive` or `ute_admin_infomodel.query_infomodel` instead.
        """
        logger.warn("Keyword ute_admin.wait_for_alarm_deletion is deprecated. "
                    "Please use ute_admin.assert_alarm_inactive or ute_admin_infomodel.query_infomodel instead.")

        return self._wait_for_alarm("deletion", parent_dist_name, alarm_properties, timeout, alias)

    def _wait_for_alarm(self, action, parent_dist_name, alarm_properties, timeout, alias):
        IsString().check(parent_dist_name)
        timeout = timestr_to_secs(timeout)
        parameters = {"operationType": action, "parentDistName": parent_dist_name, "timeout": timeout * 1000, "alarmProperties": alarm_properties}
        return self.store.get(alias).execute_infomodel_request("waitForAlarms", parameters, timeout + 10)
